import{_ as n,c as a,o as e,aN as i}from"./chunks/framework.DXgs1r1w.js";const u=JSON.parse('{"title":"MCP 协议详解","description":"","frontmatter":{"date":"2026-07-22T10:00:00.000Z","title":"MCP 协议详解","permalink":"/pages/mcp7d2","categories":["AI","MCP"]},"headers":[],"relativePath":"AI/04.MCP/MCP协议.md","filePath":"AI/04.MCP/MCP协议.md","lastUpdated":1785469254000}'),t={name:"AI/04.MCP/MCP协议.md"};function l(p,s,r,o,d,c){return e(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="mcp-协议详解" tabindex="-1">MCP 协议详解 <a class="header-anchor" href="#mcp-协议详解" aria-label="Permalink to &quot;MCP 协议详解&quot;">​</a></h1><h2 id="一、mcp-是什么" tabindex="-1">一、MCP 是什么 <a class="header-anchor" href="#一、mcp-是什么" aria-label="Permalink to &quot;一、MCP 是什么&quot;">​</a></h2><p><strong>MCP（Model Context Protocol，模型上下文协议）</strong> 是由 Anthropic 于 2024 年底提出的<strong>开放标准协议</strong>，用于让 LLM 应用以统一方式与外部数据源、工具对接。</p><ul><li>类比：<strong>MCP 之于 AI 工具，如同 USB-C 之于硬件接口</strong>——一套标准接百种设备。</li><li>解决的核心问题：在 MCP 之前，每个应用要接每个工具都要写一套定制集成，是 <strong>M × N</strong> 的复杂度；MCP 让&quot;工具按标准实现一次，任意兼容客户端复用&quot;，降为 <strong>M + N</strong>。</li></ul><h3 id="三者角色" tabindex="-1">三者角色 <a class="header-anchor" href="#三者角色" aria-label="Permalink to &quot;三者角色&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>说明</th><th>例子</th></tr></thead><tbody><tr><td><strong>Host（宿主）</strong></td><td>运行 LLM 的应用，管理多个 Client、编排工具调用</td><td>Claude Desktop、VS Code + Copilot、自建 Agent</td></tr><tr><td><strong>MCP Client</strong></td><td>由 Host 为每个 Server 创建，负责与该 Server 通信（1:1）</td><td>宿主内的连接实例</td></tr><tr><td><strong>MCP Server</strong></td><td>暴露能力的程序，可被本地或远程部署</td><td>文件系统 Server、GitHub Server、数据库 Server</td></tr></tbody></table><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────── Host（宿主应用） ───────────────────┐</span></span>
<span class="line"><span>│  LLM 引擎                                           │</span></span>
<span class="line"><span>│   ├─ MCP Client A ═══════▶ MCP Server A（文件系统）  │</span></span>
<span class="line"><span>│   ├─ MCP Client B ═══════▶ MCP Server B（GitHub）    │</span></span>
<span class="line"><span>│   └─ MCP Client C ═══════▶ MCP Server C（数据库）    │</span></span>
<span class="line"><span>└───────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>       （每个 Client 与对应 Server 1:1 连接）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><hr><h2 id="二、mcp-的核心能力-原语" tabindex="-1">二、MCP 的核心能力（原语） <a class="header-anchor" href="#二、mcp-的核心能力-原语" aria-label="Permalink to &quot;二、MCP 的核心能力（原语）&quot;">​</a></h2><p>MCP Server 可以向 Client 暴露以下几类能力：</p><table tabindex="0"><thead><tr><th>能力</th><th>方向</th><th>说明</th></tr></thead><tbody><tr><td><strong>Tools（工具）</strong></td><td>Client → Server</td><td>模型可调用的函数（查询/写操作），有 <code>tools/list</code>、<code>tools/call</code></td></tr><tr><td><strong>Resources（资源）</strong></td><td>Client → Server</td><td>类文件的数据源（日志、schema、文档），由应用决定如何使用</td></tr><tr><td><strong>Prompts（提示模板）</strong></td><td>Client → Server</td><td>预置的可复用提示词模板</td></tr><tr><td><strong>Sampling（采样）</strong></td><td>Server → Host</td><td>反向能力：Server 请求 Host 的 LLM 完成一段生成</td></tr><tr><td><strong>Roots（根目录）</strong></td><td>Host → Server</td><td>Host 告知 Server 可访问的目录边界（安全隔离）</td></tr><tr><td><strong>Logging（日志）</strong></td><td>Server → Client</td><td>Server 向 Client 推送日志消息</td></tr></tbody></table><blockquote><p>关键区分：<strong>Tools 由模型主动调用</strong>（带副作用/动作）；<strong>Resources 由应用读取</strong>（被动上下文，如把文件内容喂给模型）。</p></blockquote><hr><h2 id="三、传输层-transport" tabindex="-1">三、传输层（Transport） <a class="header-anchor" href="#三、传输层-transport" aria-label="Permalink to &quot;三、传输层（Transport）&quot;">​</a></h2><p>MCP 的通信建立在<strong>传输层</strong>之上，目前主要两种：</p><ol><li><strong>stdio（标准输入输出）</strong><ul><li>Server 作为 Host 的<strong>本地子进程</strong>启动，通过 stdin/stdout 收发 JSON-RPC 消息。</li><li>优点：简单、安全（不暴露网络端口）、适合本地工具。</li></ul></li><li><strong>Streamable HTTP / SSE（远程）</strong><ul><li>客户端用 <strong>HTTP POST</strong> 发送请求；服务端通过 <strong>SSE（Server-Sent Events）</strong> 流式推送响应与通知。</li><li>优点：支持远程/云部署、多客户端共享同一 Server。</li></ul></li></ol><h3 id="消息格式-json-rpc-2-0" tabindex="-1">消息格式：JSON-RPC 2.0 <a class="header-anchor" href="#消息格式-json-rpc-2-0" aria-label="Permalink to &quot;消息格式：JSON-RPC 2.0&quot;">​</a></h3><p>MCP 所有消息都符合 <strong>JSON-RPC 2.0</strong> 规范，分三类：</p><ul><li><strong>请求（Request）</strong>：带 <code>method</code> 和 <code>id</code>，期待响应。</li><li><strong>响应（Response）</strong>：带对应 <code>id</code> 和 <code>result</code> 或 <code>error</code>。</li><li><strong>通知（Notification）</strong>：带 <code>method</code> 但无 <code>id</code>，单向、无需回复。</li></ul><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 请求示例</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tools/list&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {} }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 响应示例</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;result&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [ </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ] } }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 通知示例（无 id）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;notifications/resources/updated&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;uri&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;file:///log.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><hr><h2 id="四、客户端与-mcp-server-的交互流程" tabindex="-1">四、客户端与 MCP Server 的交互流程 <a class="header-anchor" href="#四、客户端与-mcp-server-的交互流程" aria-label="Permalink to &quot;四、客户端与 MCP Server 的交互流程&quot;">​</a></h2><p>整个交互分为三个阶段：<strong>初始化 → 正常运行 → 关闭</strong>。下面用「Host 端的 Client」与「MCP Server」的视角，逐步拆解。</p><h3 id="阶段-1-初始化握手-initialization" tabindex="-1">阶段 1：初始化握手（Initialization） <a class="header-anchor" href="#阶段-1-初始化握手-initialization" aria-label="Permalink to &quot;阶段 1：初始化握手（Initialization）&quot;">​</a></h3><p>建立连接后，先完成<strong>协议版本协商</strong>与<strong>能力声明</strong>，双方才知道对方&quot;能做什么&quot;。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client                                          Server</span></span>
<span class="line"><span>  │                                                │</span></span>
<span class="line"><span>  │  ── initialize ───────────────────────────▶   │</span></span>
<span class="line"><span>  │     { protocolVersion,                       │</span></span>
<span class="line"><span>  │       capabilities: { tools, resources },     │</span></span>
<span class="line"><span>  │       clientInfo: { name, version } }         │</span></span>
<span class="line"><span>  │                                                │</span></span>
<span class="line"><span>  │  ◀──────────── initialize result ───────────   │</span></span>
<span class="line"><span>  │     { protocolVersion,                        │</span></span>
<span class="line"><span>  │       capabilities: { tools, resources,       │</span></span>
<span class="line"><span>  │                      prompts, logging },       │</span></span>
<span class="line"><span>  │       serverInfo: { name, version } }         │</span></span>
<span class="line"><span>  │                                                │</span></span>
<span class="line"><span>  │  ── notifications/initialized ────────────▶   │   （通知，无响应）</span></span>
<span class="line"><span>  │                                                │</span></span>
<span class="line"><span>  │        ← 此后进入正常操作阶段 →                │</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><ul><li>Client 在 <code>initialize</code> 中声明自己支持的 capabilities（如是否支持 sampling）。</li><li>Server 回告自己暴露的能力（tools/resources/prompts 等），并协商 <code>protocolVersion</code>（取双方都支持的最高版本）。</li><li>Client 收到结果后发送 <code>notifications/initialized</code> 通知，握手完成。</li></ul><h3 id="阶段-2-正常运行-operation" tabindex="-1">阶段 2：正常运行（Operation） <a class="header-anchor" href="#阶段-2-正常运行-operation" aria-label="Permalink to &quot;阶段 2：正常运行（Operation）&quot;">​</a></h3><p>握手完成后，进入双向交互。最典型的两条链路是<strong>工具发现 + 工具调用</strong>，以及资源/提示的读取。</p><h4 id="_1-工具发现-tools-list" tabindex="-1">（1）工具发现：<code>tools/list</code> <a class="header-anchor" href="#_1-工具发现-tools-list" aria-label="Permalink to &quot;（1）工具发现：\`tools/list\`&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client ── tools/list ─────────────────────▶ Server</span></span>
<span class="line"><span>Client ◀── { tools: [                      ── Server</span></span>
<span class="line"><span>              { name:&quot;query_db&quot;,</span></span>
<span class="line"><span>                description:&quot;查询数据库&quot;,</span></span>
<span class="line"><span>                inputSchema:{ type:&quot;object&quot;,</span></span>
<span class="line"><span>                  properties:{ sql:{type:&quot;string&quot;} } } } ] }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Client 用返回的工具清单（含名称、描述、入参 JSON Schema）构建给 LLM 的&quot;可用工具列表&quot;。</p><h4 id="_2-工具调用-tools-call" tabindex="-1">（2）工具调用：<code>tools/call</code> <a class="header-anchor" href="#_2-工具调用-tools-call" aria-label="Permalink to &quot;（2）工具调用：\`tools/call\`&quot;">​</a></h4><p>模型决定调用某工具后，Client 代发调用并拿回结果：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client ── tools/call ─────────────────────▶ Server</span></span>
<span class="line"><span>        { name:&quot;query_db&quot;,</span></span>
<span class="line"><span>          arguments:{ sql:&quot;SELECT * FROM users&quot; } }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Client ◀── { content:[                    ── Server</span></span>
<span class="line"><span>              { type:&quot;text&quot;,</span></span>
<span class="line"><span>                text:&quot;[{id:1,name:&#39;Ali&#39;}]&quot; } ],</span></span>
<span class="line"><span>            isError:false }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><ul><li><code>arguments</code> 必须符合工具声明的 <code>inputSchema</code>。</li><li>结果以 <code>content</code> 数组返回（可含 text / image / resource 多种块）。</li><li>Client 把结果作为<strong>新一段 Context 回灌给 LLM</strong>，模型据此继续推理（即 ReAct 循环中的 Observation）。</li></ul><h4 id="_3-资源与提示" tabindex="-1">（3）资源与提示 <a class="header-anchor" href="#_3-资源与提示" aria-label="Permalink to &quot;（3）资源与提示&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resources/list  → 列出可用资源（文件/数据源）</span></span>
<span class="line"><span>resources/read   → 读取某资源内容（按 uri）</span></span>
<span class="line"><span>prompts/list     → 列出提示模板</span></span>
<span class="line"><span>prompts/get      → 取某个模板并填充参数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h4 id="_4-server-反向请求-sampling" tabindex="-1">（4）Server 反向请求：Sampling <a class="header-anchor" href="#_4-server-反向请求-sampling" aria-label="Permalink to &quot;（4）Server 反向请求：Sampling&quot;">​</a></h4><p>Server 也能&quot;反过来&quot;请求 Host 的 LLM 能力（需 Client 在 initialize 时声明支持 sampling）：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Server ── sampling/createMessage ────────▶ Host(LLM)</span></span>
<span class="line"><span>Server ◀── { content:&quot;模型生成结果&quot; } ────── Host</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这让 Server 具备&quot;思考&quot;能力（例如根据上下文自动补全参数），而不只是被动执行。</p><h4 id="_5-通知与日志" tabindex="-1">（5）通知与日志 <a class="header-anchor" href="#_5-通知与日志" aria-label="Permalink to &quot;（5）通知与日志&quot;">​</a></h4><p>运行中 Server 可主动推送：</p><ul><li><code>notifications/resources/updated</code>：资源内容变了，提示 Client 刷新。</li><li><code>notifications/message</code>（Logging）：上报日志，便于调试。</li></ul><h3 id="阶段-3-关闭-shutdown" tabindex="-1">阶段 3：关闭（Shutdown） <a class="header-anchor" href="#阶段-3-关闭-shutdown" aria-label="Permalink to &quot;阶段 3：关闭（Shutdown）&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client ── shutdown ──────────────────────▶ Server   （请求）</span></span>
<span class="line"><span>Client ◀── {} ──────────────────────────── Server   （确认）</span></span>
<span class="line"><span>Client ── notifications/exit ────────────▶ Server   （通知，进程退出）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Client 先发 <code>shutdown</code> 请求并等确认，再发 <code>exit</code> 通知，Server 结束进程/连接。</p><hr><h2 id="五、完整时序图-一次工具调用全链路" tabindex="-1">五、完整时序图（一次工具调用全链路） <a class="header-anchor" href="#五、完整时序图-一次工具调用全链路" aria-label="Permalink to &quot;五、完整时序图（一次工具调用全链路）&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户提问          Host/Client        MCP Server         LLM</span></span>
<span class="line"><span>   │                 │                   │                │</span></span>
<span class="line"><span>   │ &quot;查用户表&quot;      │                   │                │</span></span>
<span class="line"><span>   ├────────────────▶│                   │                │</span></span>
<span class="line"><span>   │                 ├─ initialize ────▶ │  (握手)         │</span></span>
<span class="line"><span>   │                 │◀─ initialized ────┤                │</span></span>
<span class="line"><span>   │                 ├─ tools/list ────▶ │                │</span></span>
<span class="line"><span>   │                 │◀─ 工具清单 ───────┤                │</span></span>
<span class="line"><span>   │                 ├──────────────────────────────────▶│ 给工具列表</span></span>
<span class="line"><span>   │                 │◀──────────────────────────────────┤ 决定调 query_db</span></span>
<span class="line"><span>   │                 ├─ tools/call(query_db)────────────▶│</span></span>
<span class="line"><span>   │                 │◀─ 查询结果 ───────────────────────┤</span></span>
<span class="line"><span>   │                 ├──────────────────────────────────▶│ 结果回灌上下文</span></span>
<span class="line"><span>   │                 │◀──────────────────────────────────┤ 生成最终回答</span></span>
<span class="line"><span>   │◀────────────────┤                                   │</span></span>
<span class="line"><span>   │   回答 + 引用    │                   │                │</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><hr><h2 id="六、mcp-与-function-calling-的区别" tabindex="-1">六、MCP 与 Function Calling 的区别 <a class="header-anchor" href="#六、mcp-与-function-calling-的区别" aria-label="Permalink to &quot;六、MCP 与 Function Calling 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>Function Calling</th><th>MCP</th></tr></thead><tbody><tr><td>提出方</td><td>OpenAI 等模型厂商</td><td>Anthropic（开放标准）</td></tr><tr><td>层级</td><td>模型能力（&quot;模型决定调哪个函数&quot;）</td><td>传输/集成协议（&quot;应用如何连工具&quot;）</td></tr><tr><td>关注点</td><td>让模型输出结构化调用意图</td><td>定义 Client/Server 如何通信、发现、鉴权</td></tr><tr><td>复用性</td><td>每个应用各自实现接入</td><td>一次实现 Server，任意兼容客户端复用</td></tr><tr><td>关系</td><td>MCP 的 <code>tools/call</code> 可以承载 Function Calling 的语义</td><td>二者互补，不冲突</td></tr></tbody></table><blockquote><p>一句话：<strong>Function Calling 解决&quot;模型想调函数&quot;，MCP 解决&quot;应用怎么把函数接进来并管起来&quot;。</strong></p></blockquote><hr><h2 id="七、核心价值与最佳实践" tabindex="-1">七、核心价值与最佳实践 <a class="header-anchor" href="#七、核心价值与最佳实践" aria-label="Permalink to &quot;七、核心价值与最佳实践&quot;">​</a></h2><ul><li><strong>解耦</strong>：工具实现与 Host 无关，Server 可独立迭代、独立部署。</li><li><strong>安全边界</strong>：通过 Roots 限制可访问目录，通过权限控制工具调用（配合 Human-in-the-Loop）。</li><li><strong>可组合</strong>：一个 Host 同时连多个 Server，能力按需拼接。</li><li><strong>最佳实践</strong>： <ol><li>工具描述（description）写清楚，模型才能正确选工具。</li><li>入参用 JSON Schema 严格约束，减少非法调用。</li><li>远程 Server 务必做鉴权与传输加密。</li><li>危险操作叠加人工确认，避免模型误调。</li></ol></li></ul><blockquote><p>记忆口诀：<strong>MCP = 统一接口标准；Host 管编排、Client 一对一连、Server 供能力；先 initialize 协商，再 tools/list 发现、tools/call 调用，结果回灌 LLM 续推。</strong></p></blockquote>`,59)])])}const b=n(t,[["render",l]]);export{u as __pageData,b as default};
